function convertDateFormat(dateString) {
    // Split the date string into year and month
    const [year, month] = dateString.split('/');

    // Create a new Date object using the provided year and month
    const date = new Date(`${year}-${month}-01`);

    // Get the formatted date string in the desired format (MM/YY)
    const formattedDate = date.toLocaleDateString('en-US', {
      year: '2-digit',
      month: '2-digit'
    });

    // Return the formatted date string
    return formattedDate.substring(0, 5);
}

function containsNumber(inputString) {
    return /\d/.test(inputString);
}

function minMaxLenght(inputString, minLength, maxLength) {
    return inputString.length >= minLength && inputString.length <= maxLength;
}

function lengthCheck(value, expectedLength) {
    return value.length === expectedLength;
}

function onlyNumbers(value) {
    return /^\d+$/.test(value);
}

function validExpiryDate(date) {
    var currentDate = new Date();
    var currentYear = currentDate.getFullYear() % 100; 
    var currentMonth = currentDate.getMonth() + 1; 

    var parts = date.split('/');
    var month = parseInt(parts[0], 10);
    var year = parseInt(parts[1], 10);

    return (year > currentYear) || (year === currentYear && month >= currentMonth);
}

function isValidCardNumber(number) {
    var digit, digits, sum, i, len;
    sum = 0;
    digits = (number + '').split('').reverse();
    for (i = 0, len = digits.length; i < len; i++) {
        digit = digits[i];
        digit = parseInt(digit, 10);
        if ((i % 2) === 1) {
            digit *= 2;
            if (digit > 9) {
                digit -= 9;
            }
        }
        sum += digit;
    }
    return (sum % 10) === 0;
}

